# Appends/replaces the Q3 entries of /output/report.json (idempotent: entries whose quantity starts with 'Q3' are removed first).
import json,shutil
P='/output/report.json'; r=json.load(open(P))
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q3')]
r['recipe']=[x for x in r['recipe'] if not x['description'].startswith('Q3')]
r['caveats']=[x for x in r['caveats'] if not x.startswith('Q3')]
r['datasets']=[d for d in r['datasets'] if not d['role'].startswith('Q3')]
A=lambda n,v,u=None:{'name':n,'value':v,'unit':u}
common=[A('Vsys (fiducial, radio LSRK)','2775','km/s'),A('beam','Xb4d cubes convolved channel-by-channel to a 1.05" circular beam (native 0.94x0.74")')]
def R(q,v,u,c,e,t=None,note=None,un=None,a2=None):
    if isinstance(note,list): a2,note=note,None
    a=a2 if a2 is not None else common+([A('note',note)] if note else [])
    return {'quantity':q,'target':t,'value':v,'uncertainty':un,'unit':u,'assumptions':a,'confidence':c,'evidence':e}
